-- SQL DDL for ClickHouse, generated by ormbridge.

CREATE TABLE blog_item (
  id Int32,
  first_name String,
  last_name String,
  full_name String COMMENT 'generated column written as a regular column',
  quantity Int32 DEFAULT 1,
  total_cents Int32 ALIAS quantity * 100,
  tags Array(String) DEFAULT [],
  grid Array(Array(Int32)),
  kinds Array(Enum8('tool' = 1, 'toy' = 2)) DEFAULT [],
  attributes Map(String, String),
  stock_range Nullable(String) COMMENT 'range stored as text',
  big_range Nullable(String) COMMENT 'range stored as text',
  price_range Nullable(String) COMMENT 'range stored as text',
  available Nullable(String) COMMENT 'range stored as text',
  valid_during Nullable(String) COMMENT 'range stored as text',
  last_ip Nullable(IPv6),
  legacy_ip Nullable(IPv6),
  shelf_life Nullable(Int64) COMMENT 'duration in microseconds',
  source_path Nullable(String),
  manual Nullable(String),
  photo Nullable(String),
  small_count Int32 DEFAULT 0,
  tiny_count Int32 DEFAULT 0,
  is_active Bool DEFAULT true,
  stocked_at DateTime64(3) DEFAULT now64(3),
  priority Int32 DEFAULT 5,
  note String DEFAULT 'none'
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE blog_counter (
  small_id Int32,
  label String
)
ENGINE = MergeTree()
ORDER BY (small_id)
PRIMARY KEY (small_id);

CREATE TABLE blog_shipment (
  id Int32,
  object_id Int32,
  item_id Int32,
  other_id Int32,
  content_type_id Int32,
  created_by_id Int32
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE blog_account (
  id Int32,
  email String
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE blog_assignment (
  item_id Int32,
  account_id Int32
)
ENGINE = MergeTree()
ORDER BY (item_id, account_id)
PRIMARY KEY (item_id, account_id);

CREATE TABLE blog_contenttype (
  id Int32
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);
